#include <stdio.h>

void greet() {
    printf("Hello!\n");
}

// Function taking a function pointer as argument
void execute(void (*func)()) {
    printf("Executing callback...\n");
    func(); // Call the passed function
}

int main() {
    // Pass 'greet' function as argument
    execute(greet);
    return 0;
}
